'use strict';

const nconf = require('nconf');

const user = require('./index');
const utils = require('../utils');
const plugins = require('../plugins');
const db = require('../database');
const meta = require('../meta');
const emailer = require('../emailer');
const groups = require('../groups');
const events = require('../events');

const UserEmail = module.exports;

UserEmail.exists = async function (email) {
	const uid = await user.getUidByEmail(email.toLowerCase());
	return !!uid;
};

UserEmail.available = async function (email) {
	const exists = await db.isSortedSetMember('email:uid', email.toLowerCase());
	return !exists;
};

UserEmail.sendValidationEmail = async function (uid, options) {
	/*
	 * 	Options:
	 * 		- email, overrides email retrieval
	 * 		- force, sends a new email even if a non-expired validation email is already pending
	 */

	uid = parseInt(uid, 10);
	options = options || {};

	// Fallback behaviour (email passed in as second argument)
	if (typeof options === 'string') {
		options = {
			email: options,
		};
	}

	let confirm_code = utils.generateUUID();
	const confirm_link = `${nconf.get('url')}/confirm/${confirm_code}`;

	// If no email passed in (default), retrieve email from uid
	if (!options.email || !options.email.length) {
		options.email = await UserEmail.getEmailForValidation(uid);
	}
	if (!options.email) {
		return;
	}

	// Prevent a new email from being sent to an address that is already the user's confirmed email
	const currentEmail = await user.getUserField(uid, 'email');
	if (currentEmail && currentEmail.toLowerCase() === options.email.toLowerCase()) {
		throw new Error('[[error:email-nochange]]');
	}

	// Do not send a new email while a non-expired one is already pending for this user
	if (!options.force && await UserEmail.isValidationPending(uid, options.email)) {
		throw new Error('[[error:confirm-email-already-sent]]');
	}

	// Replace any existing (possibly expired) confirmation for this user
	const oldCode = await db.get(`confirm:byUid:${uid}`);
	if (oldCode && oldCode !== confirm_code) {
		await db.delete(`confirm:${oldCode}`);
	}

	confirm_code = await plugins.hooks.fire('filter:user.verify.code', confirm_code);

	// `confirm:byUid:<uid>` -> <code>, `confirm:<code>` -> { email, uid, expires }
	const expires = Date.now() + (60 * 60 * 24 * 1000);
	await Promise.all([
		db.set(`confirm:byUid:${uid}`, confirm_code),
		db.setObject(`confirm:${confirm_code}`, {
			email: options.email.toLowerCase(),
			uid,
			expires,
		}),
	]);
	const username = await user.getUserField(uid, 'username');

	events.log({
		type: 'email-confirmation-sent',
		uid,
		confirm_code,
		...options,
	});

	const data = {
		username: username,
		confirm_link: confirm_link,
		confirm_code: confirm_code,

		subject: options.subject || `[[email:welcome-to, ${meta.config.title || meta.config.browserTitle || 'NodeBB'}]]`,
		template: options.template || 'welcome',
		uid: uid,
	};

	if (plugins.hooks.hasListeners('action:user.verify')) {
		plugins.hooks.fire('action:user.verify', { uid: uid, data: data });
	} else {
		await emailer.send(data.template, uid, data);
	}
	return confirm_code;
};

// Get the email to use for validation actions: the user's primary email,
// falling back to the email stored in any pending (or expired) confirmation object
UserEmail.getEmailForValidation = async function (uid) {
	uid = parseInt(uid, 10);
	const email = await user.getUserField(uid, 'email');
	if (email) {
		return email;
	}
	const code = await db.get(`confirm:byUid:${uid}`);
	if (!code) {
		return null;
	}
	const confirmObj = await db.getObject(`confirm:${code}`);
	if (confirmObj && confirmObj.uid && parseInt(confirmObj.uid, 10) === uid && confirmObj.email) {
		return confirmObj.email;
	}
	return null;
};

// Check if an email confirmation is currently pending for a user
UserEmail.isValidationPending = async function (uid, email) {
	uid = parseInt(uid, 10);
	const code = await db.get(`confirm:byUid:${uid}`);
	if (!code) {
		return false;
	}
	const confirmObj = await db.getObject(`confirm:${code}`);
	if (!confirmObj || !confirmObj.uid || !confirmObj.email) {
		return false;
	}
	if (parseInt(confirmObj.uid, 10) !== uid) {
		return false;
	}
	if (email && String(email).toLowerCase() !== confirmObj.email.toLowerCase()) {
		return false;
	}
	const expires = parseInt(confirmObj.expires, 10);
	return !!(Number.isNaN(expires) ? (confirmObj.expires > Date.now()) : (expires > Date.now()));
};

// Expire any pending email confirmation for a user
UserEmail.expireValidation = async function (uid) {
	uid = parseInt(uid, 10);
	const code = await db.get(`confirm:byUid:${uid}`);
	if (!code) {
		return;
	}
	await db.deleteAll([`confirm:byUid:${uid}`, `confirm:${code}`]);
};

// confirm email by code sent by confirmation email
UserEmail.confirmByCode = async function (code) {
	const confirmObj = await db.getObject(`confirm:${code}`);
	if (!confirmObj || !confirmObj.uid || !confirmObj.email) {
		throw new Error('[[error:invalid-data]]');
	}

	const uid = parseInt(confirmObj.uid, 10);
	const storedCode = await db.get(`confirm:byUid:${uid}`);
	if (!storedCode || storedCode !== code) {
		// Stale or unknown code (e.g. replaced by a more recent confirmation)
		throw new Error('[[error:invalid-data]]');
	}
	const expires = parseInt(confirmObj.expires, 10);
	if (!Number.isNaN(expires) && expires <= Date.now()) {
		// Expired confirmation code
		await db.deleteAll([`confirm:byUid:${uid}`, `confirm:${code}`]);
		throw new Error('[[error:invalid-data]]');
	}

	let oldEmail = await user.getUserField(uid, 'email');
	if (oldEmail) {
		oldEmail = oldEmail || '';
		if (oldEmail === confirmObj.email) {
			await Promise.all([
				UserEmail.confirmByUid(uid),
				db.delete(`confirm:${code}`),
			]);
			return;
		}

		await db.sortedSetRemove('email:uid', oldEmail.toLowerCase());
		await db.sortedSetRemove('email:sorted', `${oldEmail.toLowerCase()}:${uid}`);
		await user.auth.revokeAllSessions(uid);
		await events.log('email-change', { oldEmail, newEmail: confirmObj.email });
	}

	await Promise.all([
		user.setUserField(uid, 'email', confirmObj.email),
		UserEmail.confirmByUid(uid),
		db.delete(`confirm:${code}`),
	]);
};

// confirm uid's email via ACP
UserEmail.confirmByUid = async function (uid) {
	uid = parseInt(uid, 10);
	if (!(uid > 0)) {
		throw new Error('[[error:invalid-uid]]');
	}
	const currentEmail = await user.getUserField(uid, 'email');
	if (!currentEmail) {
		throw new Error('[[error:invalid-email]]');
	}

	await Promise.all([
		db.sortedSetAddBulk([
			['email:uid', uid, currentEmail.toLowerCase()],
			['email:sorted', 0, `${currentEmail.toLowerCase()}:${uid}`],
			[`user:${uid}:emails`, Date.now(), `${currentEmail}:${Date.now()}`],
		]),
		user.setUserField(uid, 'email:confirmed', 1),
		groups.join('verified-users', uid),
		groups.leave('unverified-users', uid),
		user.reset.cleanByUid(uid),
	]);
	// Expire any pending confirmations now that the email has been validated
	await UserEmail.expireValidation(uid);
	await plugins.hooks.fire('action:user.email.confirmed', { uid: uid, email: currentEmail });
};
